#!/bin/bash
set -e
echo "Fixing discover route..."
mkdir -p src/app/api/discover
echo  | base64 -d > src/app/api/discover/route.ts
echo "✓ src/app/api/discover/route.ts"
git add -A
git commit -m "fix: discover route — better search queries, smarter domain filtering"
git push origin main
vercel --prod
echo "✅ Done!"